const listUserCapabilities = `-- name: ListUserCapabilities :many
SELECT DISTINCT unnest(pg.capabilities)::text AS capability
FROM user_permission_groups upg
JOIN permission_groups pg ON pg.id = upg.permission_group_id AND pg.active
WHERE upg.user_id = $1
`

func (q *Queries) ListUserCapabilities(ctx context.Context, userID uuid.UUID) ([]string, error) {
	rows, err := q.db.Query(ctx, listUserCapabilities, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var capability string
		if err := rows.Scan(&capability); err != nil {
			return nil, err
		}
		items = append(items, capability)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listWindowsBetween = `-- name: ListWindowsBetween :many
SELECT w.id, w.title, w.starts_at, w.ends_at, w.suppress_notifications, w.agenda_task_id,
  COALESCE(s.name, a.name, tu.name, o.name, ar.name, t.name, '')::text AS target_name,
  COALESCE(w.area_id, a.area_id, t.area_id, '00000000-0000-0000-0000-000000000000'::uuid) AS area_id, w.organization_id, s.organization_id AS service_org_id, a.client_id AS asset_client_id
FROM maintenance_windows w
LEFT JOIN services s ON s.id = w.service_id
LEFT JOIN assets a ON a.id = w.asset_id
LEFT JOIN territorial_units tu ON tu.id = w.territorial_unit_id
LEFT JOIN organizations o ON o.id = w.organization_id
LEFT JOIN areas ar ON ar.id = w.area_id
LEFT JOIN teams t ON t.id = w.team_id
WHERE w.active AND w.starts_at < $1::timestamptz AND w.ends_at > $2::timestamptz
ORDER BY w.starts_at
`

type ListWindowsBetweenParams struct {
	ToAt   pgtype.Timestamptz `json:"to_at"`
	FromAt pgtype.Timestamptz `json:"from_at"`
}

type ListWindowsBetweenRow struct {
	ID                    uuid.UUID          `json:"id"`
	Title                 string             `json:"title"`
	StartsAt              pgtype.Timestamptz `json:"starts_at"`
	EndsAt                pgtype.Timestamptz `json:"ends_at"`
	SuppressNotifications bool               `json:"suppress_notifications"`
	AgendaTaskID          pgtype.UUID        `json:"agenda_task_id"`
	TargetName            string             `json:"target_name"`
	AreaID                uuid.UUID          `json:"area_id"`
	OrganizationID        pgtype.UUID        `json:"organization_id"`
	ServiceOrgID          pgtype.UUID        `json:"service_org_id"`
	AssetClientID         pgtype.UUID        `json:"asset_client_id"`
}

// Para el calendario de la Agenda: las ventanas activas que tocan el rango.
func (q *Queries) ListWindowsBetween(ctx context.Context, arg ListWindowsBetweenParams) ([]ListWindowsBetweenRow, error) {
	rows, err := q.db.Query(ctx, listWindowsBetween, arg.ToAt, arg.FromAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListWindowsBetweenRow
	for rows.Next() {
		var i ListWindowsBetweenRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.StartsAt,
			&i.EndsAt,
			&i.SuppressNotifications,
			&i.AgendaTaskID,
			&i.TargetName,
			&i.AreaID,
			&i.OrganizationID,
			&i.ServiceOrgID,
			&i.AssetClientID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listWindowsToNotify = `-- name: ListWindowsToNotify :many

SELECT w.id, w.title, w.starts_at, w.ends_at, w.notified_start, w.notified_end, w.created_by,
  COALESCE(w.area_id, a.area_id, t.area_id, '00000000-0000-0000-0000-000000000000'::uuid) AS area_id
FROM maintenance_windows w
LEFT JOIN assets a ON a.id = w.asset_id
LEFT JOIN teams t ON t.id = w.team_id
WHERE w.active AND ((NOT w.notified_start AND w.starts_at <= now()) OR (NOT w.notified_end AND w.ends_at <= now()))
`

type ListWindowsToNotifyRow struct {
	ID            uuid.UUID          `json:"id"`
	Title         string             `json:"title"`
	StartsAt      pgtype.Timestamptz `json:"starts_at"`
	EndsAt        pgtype.Timestamptz `json:"ends_at"`
	NotifiedStart bool               `json:"notified_start"`
	NotifiedEnd   bool               `json:"notified_end"`
	CreatedBy     uuid.UUID          `json:"created_by"`
	AreaID        uuid.UUID          `json:"area_id"`
}

// ===== Ventanas de mantenimiento (avisos y Agenda) =====
// Ventanas que empezaron o terminaron y todavía no se avisaron, con el área
// a la que se le avisa: la de la ventana, la del activo o la del equipo.
func (q *Queries) ListWindowsToNotify(ctx context.Context) ([]ListWindowsToNotifyRow, error) {
	rows, err := q.db.Query(ctx, listWindowsToNotify)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListWindowsToNotifyRow
	for rows.Next() {
		var i ListWindowsToNotifyRow
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.StartsAt,
			&i.EndsAt,
			&i.NotifiedStart,
			&i.NotifiedEnd,
			&i.CreatedBy,
			&i.AreaID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

