const shiftTaskWindows = `-- name: ShiftTaskWindows :execrows
UPDATE maintenance_windows SET starts_at = starts_at + make_interval(days => $2::int),
  ends_at = ends_at + make_interval(days => $2::int)
WHERE agenda_task_id = $1 AND active AND starts_at > now()
`

